.tp-wrap{
  position:relative;
}
.tp-popover{
  position:absolute;
  top:calc(100% + var(--s-1));
  left:0;
  width:200px;
  background:var(--obsidian-900);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-lg);
  box-shadow:var(--sh-3);
  padding:var(--s-3);
  z-index:var(--z-popover);
  font-family:var(--font-sans);
  opacity:0;
  transform:translateY(-4px);
  pointer-events:none;
  transition:opacity var(--d-quick) var(--ease-accel), transform var(--d-quick) var(--ease-accel);
}
.tp-popover.is-open{
  opacity:1;
  transform:translateY(0);
  pointer-events:auto;
  transition:opacity var(--d-quick) var(--ease-decel), transform var(--d-quick) var(--ease-decel);
}
.tp-popover[hidden]{
  display:none;
}
.tp-wheels{
  position:relative;
  display:grid;
  grid-template-columns:1fr auto 1fr;
  align-items:center;
  height:calc(28px * 7);
  --tp-item-h:28px;
  --tp-visible:7;
  --tp-center:3;
}
.tp-sep{
  font-family:var(--font-sans);
  font-size:var(--t-lead);
  font-weight:600;
  color:var(--obsidian-300);
  padding:0 var(--s-1);
}
.tp-wheels::before{
  content:"";
  position:absolute;
  left:0;
  right:0;
  top:calc(var(--tp-item-h) * var(--tp-center));
  height:var(--tp-item-h);
  background:color-mix(in srgb, var(--primary-500) calc(var(--tint-fill) * 100%), transparent);
  border-top:var(--bw-1) solid color-mix(in srgb, var(--primary-500) calc(var(--tint-glow) * 100%), transparent);
  border-bottom:var(--bw-1) solid color-mix(in srgb, var(--primary-500) calc(var(--tint-glow) * 100%), transparent);
  pointer-events:none;
  border-radius:var(--r-sm);
}
.tp-wheels::after{
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient(180deg, var(--obsidian-900) 0%, color-mix(in srgb, var(--obsidian-900) calc(var(--tint-strong) * 100%), transparent) 14%, transparent 36%, transparent 64%, color-mix(in srgb, var(--obsidian-900) calc(var(--tint-strong) * 100%), transparent) 86%, var(--obsidian-900) 100%);
  pointer-events:none;
  border-radius:var(--r-sm);
}
.tp-wheel{
  height:100%;
  overflow-y:scroll;
  scroll-snap-type:y mandatory;
  scrollbar-width:none;
  -ms-overflow-style:none;
  scroll-behavior:smooth;
}
.tp-wheel::-webkit-scrollbar{
  display:none;
}
.tp-wheel-list{
  padding:calc(var(--tp-item-h) * var(--tp-center)) 0;
}
.tp-wheel-item{
  height:var(--tp-item-h);
  display:grid;
  place-items:center;
  font-family:var(--font-sans);
  font-size:var(--t-small);
  font-variant-numeric:tabular-nums;
  color:var(--obsidian-400);
  scroll-snap-align:center;
  scroll-snap-stop:always;
  cursor:pointer;
  transition:color var(--d-quick) var(--ease-standard), font-weight var(--d-quick) var(--ease-standard);
}
.tp-wheel-item.is-active{
  color:var(--obsidian-100);
  font-weight:600;
}
.tp-wheel:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:calc(-1 * var(--s-0-5));
  box-shadow:var(--ring-halo);
  border-radius:var(--r-sm);
}
@media (prefers-reduced-motion: reduce){
  .tp-popover, .tp-wheel-item{
    transition:none;
  }
  .tp-wheel{
    scroll-behavior:auto;
  }
}
.tp-wheel-item:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
.tp-popover{
  display:block;
}
.tp-popover{
  position:static;
  margin-top:var(--s-6);
  max-height:none;
  opacity:1;
  transform:none;
  pointer-events:auto;
}
